import{_ as i,o as r,c as s,ah as a}from"./chunks/framework.C5RNlfrV.js";const t="/projects/AiNex/en/raspberry-pi5-version/assets/image2.DKvkkrRf.png",o="/projects/AiNex/en/raspberry-pi5-version/assets/image3.B-VEjEdw.png",p="/projects/AiNex/en/raspberry-pi5-version/assets/image4.CefqmXCZ.png",l="/projects/AiNex/en/raspberry-pi5-version/assets/image5.D7ZDSBam.png",d="/projects/AiNex/en/raspberry-pi5-version/assets/image6.B9qD8HQj.png",n="/projects/AiNex/en/raspberry-pi5-version/assets/image7.Crzdjt9Q.png",c="data:image/png;base64,",h="data:image/png;base64,",x=JSON.parse('{"title":"10. AiNex Upgrade Instruction","description":"","frontmatter":{},"headers":[],"relativePath":"docs/10.AiNex Upgrade Instruction.md","filePath":"docs/10.AiNex Upgrade Instruction.md"}'),g={name:"docs/10.AiNex Upgrade Instruction.md"};function y(m,e,A,u,b,f){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="_10-ainex-upgrade-instruction" tabindex="-1">10. AiNex Upgrade Instruction <a class="header-anchor" href="#_10-ainex-upgrade-instruction" aria-label="Permalink to &quot;10. AiNex Upgrade Instruction&quot;">​</a></h1><h2 id="_10-1-upgrade-instruction-of-ainex-raspberry-pi-5-version" tabindex="-1">10.1 Upgrade Instruction of AiNex Raspberry Pi 5 Version <a class="header-anchor" href="#_10-1-upgrade-instruction-of-ainex-raspberry-pi-5-version" aria-label="Permalink to &quot;10.1 Upgrade Instruction of AiNex Raspberry Pi 5 Version&quot;">​</a></h2><p>AiNex offers two versions of the main controller, Raspberry Pi 4B and Raspberry Pi 5, for you to choose from.</p><p>The AiNex of Raspberry Pi 5 version has also received upgrades on the expansion board. This provides AiNex higher performance and faster response speed in functions such as motion control and vision applications.</p><p>The differences between the Raspberry Pi 4B and Raspberry Pi 5 versions of AiNex are shown below:</p><table><colgroup><col style="width:17%;"><col style="width:19%;"><col style="width:30%;"><col style="width:32%;"></colgroup><tbody><tr><td style="text-align:center;">No.</td><td style="text-align:center;">Name</td><td style="text-align:center;"><p>Raspberry Pi 4B</p><p>version</p></td><td style="text-align:center;"><p>Raspberry Pi 5</p><p>version</p></td></tr><tr><td rowspan="2" style="text-align:center;">1</td><td rowspan="2" style="text-align:center;">Model</td><td style="text-align:center;"><img loading="lazy" height="484" width="387" src="'+t+'" class="common_img" style="width:156px;"></td><td style="text-align:center;"><img loading="lazy" height="484" width="387" src="'+t+'" class="common_img" style="width:156px;"></td></tr><tr><td colspan="2" style="text-align:center;">The appearance remains the same.</td></tr><tr><td rowspan="2" style="text-align:center;">2</td><td rowspan="2" style="text-align:center;"><p>Upgrade</p><p>controller</p></td><td style="text-align:center;"><p><img loading="lazy" height="400" width="400" src="'+o+'" class="common_img" style="width:175px;"></p><p>Raspberry Pi 4B</p></td><td style="text-align:center;"><p><img loading="lazy" height="259" width="385" src="'+p+'" class="common_img" style="width:150px;"></p><p>Raspberry Pi 5</p></td></tr><tr><td colspan="2" style="text-align:center;"><p>For the introduction of Raspberry Pi 4B</p><p>and 5, please refer to “4.Raspberry Pi</p><p>Board &amp; Expansion Board Course”.</p></td></tr><tr><td rowspan="2" style="text-align:center;">3</td><td rowspan="2" style="text-align:center;"><p>ROS</p><p>version</p></td><td style="text-align:center;">Noetic Ninjemys</td><td style="text-align:center;">Noetic Ninjemys</td></tr><tr><td colspan="2" style="text-align:center;"><p>The ROS system for the Raspberry Pi 5</p><p>version is built into a Docker container of Ubuntu 20.04, which achieves</p><p>compatibility between different versions of ROS and the operating system, and</p><p>improves the security of ROS updates</p><p>and running processes.</p></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;"><p>Underlying</p><p>system</p></td><td style="text-align:center;">Debian 10</td><td style="text-align:center;">Debian 12</td></tr><tr><td rowspan="2" style="text-align:center;">5</td><td rowspan="2" style="text-align:center;"><p>Upgrade</p><p>expansion board</p></td><td style="text-align:center;"><p>Equipped with an</p><p>IC chip</p></td><td style="text-align:center;"><p>Equipped with a</p><ol start="32" type="1"><li><p>bit ARM main</p><p>controller chip</p></li></ol></td></tr><tr><td colspan="2" style="text-align:center;"><p>Equipped with a 32-bit ARM main</p><p>controller chip that communicates via the CRC (Cyclic Redundancy Check)</p><p>algorithm, enhancing the reliability and</p><p>integrity of data transmission.</p></td></tr><tr><td rowspan="2" style="text-align:center;">6</td><td rowspan="2" style="text-align:center;"><p>Cooling</p><p>method</p></td><td style="text-align:center;"><p><img loading="lazy" height="86" width="130" src="'+l+'" class="inline-icon"></p><p>Heat sink</p></td><td style="text-align:center;"><p><img loading="lazy" height="148" width="166" src="'+d+'" class="inline-icon"></p><p>Active cooling fan + silicone thermal pads</p></td></tr><tr><td colspan="2" style="text-align:center;"><p>Raspberry Pi 5 is equipped with an</p><p>active cooling fan and silicone thermal pads. The fan speed is dynamically</p><p>adjusted with the changes in CPU</p><p>temperature, greatly reducing the</p><p>impact of temperature on the</p><p>performance of Raspberry Pi 5.</p></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">Accessories</td><td style="text-align:center;"><p><img loading="lazy" height="86" width="106" src="'+n+'" class="inline-icon"></p><p>Raspberry Pi 4B</p><p>needs two</p><p>double-channel</p><p>nylon pillars (M2.5*10) to be</p><p>connected with the expansion board.</p></td><td style="text-align:center;"><p><img loading="lazy" height="86" width="106" src="'+n+'" class="inline-icon"></p><p>Raspberry Pi 5</p><p>needs two</p><p>double-channel</p><p>nylon pillars (M2.5*</p><p>16) to be connected with the expansion board.</p></td></tr></tbody></table><ol><li>In terms of <strong>appearance</strong>, except for the difference in the main controller, the overall design remains the same.</li></ol><p>2. In terms of the <strong>built-in system</strong>, the Raspberry Pi 4B version of AiNex comes with Debian 10 as the operating system and pre-installed ROS Noetic Ninjemys. All software, function programs run on this system.</p><p>On the other hand, the Raspberry Pi 5 version comes with Debian 12. A Docker container system of Ubuntu 20.04 and ROS Noetic Ninjemys are created as the development environment for AiNex.</p><p>By using Docker container technology, the Raspberry Pi 5 version isolates the ROS running environment. It not only keeps the basic operating system stable, but also provides a separate and easier-to-maintain environment for ROS. This achieves compatibility between different versions of ROS and the operating system, improves the security of ROS updates and runtime processes, and allows for better isolation of system resources and unified runtime environments across different platforms, which in turn brings portability to development and testing.</p><ol start="3"><li>Regarding <strong>function games</strong>, the new version remains largely consistent with the previous one. The only difference is that to stop the ROS service, you need to run the “~/.stop_ros.sh” script under Docker. To start it, you need to exit the Docker environment and enable the automatic startup service with “sudo systemctl restart start_node.service”.</li></ol><p>4. There are significant differences in the <strong>underlying control</strong> of AiNex&#39;s Raspberry Pi 4B and Raspberry Pi 5 versions. The Raspberry Pi 4B version of AiNex uses an expansion board loaded with an IC chip. It communicates with the IC chip through the I2C communication protocol, achieving the control for the underlying hardware, such as servos and LED lights with the GPIO port.</p><p>After being upgraded, the expansion board for the Raspberry Pi 5 version is equipped with a 32-bit ARM master control chip. It adopts CRC (Cyclic Redundancy Check) algorithm to communicate with the 32-bit ARM master control chip to drive the underlying hardware. This upgrade greatly improves the reliability and integrity of data transmission, as well as the response speed of AiNex’s underlying control.</p><ol start="5"><li><p>The <strong>courses</strong> for both versions of AiNex are still highly universal and not changed much. Therefore, most of the video demonstrations are still based on the 4B version, which is equally applicable to the Raspberry Pi 5 version.</p></li><li><p>For <strong>terminal usage</strong>, when using MobaXterm to connect, you need to enter commands to enter the Docker environment. When using VNC to connect, there are two terminals to choose from. <img loading="lazy" height="37" width="40" src="'+c+'" class="inline-icon"> accesses directly to the Docker environment. <img loading="lazy" height="31" width="39" src="'+h+'" class="inline-icon">requires you to enter commands to enter the Docker environment.</p></li></ol><p>With the same appearance, more detailed tutorials, more powerful controller, and more stable expansion board, AiNex greatly enhances your experience and expands its playability.</p>',15)])])}const v=i(g,[["render",y]]);export{x as __pageData,v as default};
